#!/usr/bin/env python3
"""Collect one candidate-bound TUI-02 read-only probe.

This script is intentionally a collector, not a checkpoint writer or gate
evaluator.  It only performs Docker inspect/volume inspect and HTTP GETs.  It
does not restart services, change configuration, issue business requests, or
write a file.  Prometheus credentials are read from the host-only JSON file
and are never included in output.
"""

from __future__ import annotations

import argparse
import base64
import hashlib
import ipaddress
import json
import math
import re
import ssl
import subprocess
import sys
from collections import Counter
from datetime import UTC, datetime
from pathlib import Path
from stat import S_IMODE
from typing import Any, cast
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode, urlsplit, urlunsplit
from urllib.request import (
    HTTPRedirectHandler,
    ProxyHandler,
    Request,
    build_opener,
)


EXPECTED_RELEASE = "20260908163105"
EXPECTED_COMMIT = "b79687e46de05725c7cbea2cd135a040141ca331"
EXPECTED_IMAGE_ID = "sha256:22661f49c8ded9b040da18e524e93dba1c24558de7a1f67a8fff2a8b63d06562"
CREDENTIAL_PATH = Path("/opt/agomtradepro/ops-secrets/prometheus-query.credentials")
MAX_REQUEST_SECONDS = 20
MAX_PROMETHEUS_POINTS = 11_000
MAX_RESPONSE_BYTES = 16 * 1024 * 1024
COMMIT_RE = re.compile(r"^[0-9a-f]{40}$")
RELEASE_RE = re.compile(r"^[0-9]{14}$")


class ProbeBlocked(RuntimeError):
    """Raised for a fail-closed collection boundary."""

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


class _NoRedirect(HTTPRedirectHandler):
    """Never forward a credential-bearing GET to a redirected origin."""

    def redirect_request(self, *args: Any, **kwargs: Any) -> Request | None:
        """Reject redirects instead of following them."""

        raise ProbeBlocked("http_redirect_rejected")


def _utc_text(value: datetime) -> str:
    """Serialize an aware UTC timestamp without exposing local timezone data."""

    return value.astimezone(UTC).isoformat(timespec="microseconds").replace("+00:00", "Z")


def _parse_utc(value: object) -> datetime:
    """Parse Docker or API UTC text into an aware UTC datetime."""

    if type(value) is not str:
        raise ProbeBlocked("docker_timestamp_missing")
    text = value.strip()
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as exc:
        raise ProbeBlocked("docker_timestamp_invalid") from exc
    if parsed.tzinfo is None or parsed.utcoffset() != datetime.now(UTC).utcoffset():
        raise ProbeBlocked("docker_timestamp_not_utc")
    return parsed.astimezone(UTC)


def _mapping(value: object) -> dict[str, Any]:
    """Narrow a JSON object at an inspect/API boundary."""

    if not isinstance(value, dict) or any(type(key) is not str for key in value):
        raise ProbeBlocked("json_object_expected")
    return cast(dict[str, Any], value)


def _docker_text(args: list[str]) -> str:
    """Run one read-only Docker CLI command without exposing stderr."""

    try:
        completed = subprocess.run(
            ["docker", *args],
            check=True,
            capture_output=True,
            text=True,
            timeout=MAX_REQUEST_SECONDS,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise ProbeBlocked("docker_command_failed") from exc
    return completed.stdout


def _docker_json(args: list[str]) -> object:
    """Run one read-only Docker command and decode its JSON response."""

    output = _docker_text(args)
    try:
        return json.loads(output)
    except json.JSONDecodeError as exc:
        raise ProbeBlocked("docker_json_invalid") from exc


def _inspect_container(container_id: str) -> dict[str, Any]:
    """Inspect one container ID returned by Docker itself."""

    value = _docker_json(["inspect", container_id])
    if not isinstance(value, list) or len(value) != 1:
        raise ProbeBlocked("docker_container_inspect_invalid")
    return _mapping(value[0])


def _labels(container: dict[str, Any]) -> dict[str, str]:
    """Return only string Docker labels."""

    config = _mapping(container.get("Config"))
    raw = config.get("Labels")
    if raw is None:
        return {}
    labels = _mapping(raw)
    return {key: value for key, value in labels.items() if type(value) is str}


def _running_service(service: str, *, project: str | None = None) -> dict[str, Any]:
    """Select exactly one running non-oneoff Compose service container."""

    output = _docker_text(
        ["ps", "-aq", "--filter", f"label=com.docker.compose.service={service}"]
    )
    candidates: list[dict[str, Any]] = []
    for container_id in (line.strip() for line in output.splitlines()):
        if not container_id:
            continue
        container = _inspect_container(container_id)
        labels = _labels(container)
        if labels.get("com.docker.compose.service") != service:
            continue
        if labels.get("com.docker.compose.oneoff", "false").lower() == "true":
            continue
        if project is not None and labels.get("com.docker.compose.project") != project:
            continue
        state = _mapping(container.get("State"))
        if state.get("Status") != "running":
            continue
        candidates.append(container)
    if len(candidates) != 1:
        raise ProbeBlocked(f"canonical_{service}_container_count")
    return candidates[0]


def _image_info(container: dict[str, Any]) -> tuple[str, str, str | None]:
    """Read the immutable image ID, configured reference, and OCI revision."""

    config = _mapping(container.get("Config"))
    image_ref = config.get("Image")
    if type(image_ref) is not str or not image_ref:
        raise ProbeBlocked("web_configured_image_missing")
    image_payload = _docker_json(["image", "inspect", image_ref])
    if not isinstance(image_payload, list) or len(image_payload) != 1:
        raise ProbeBlocked("web_image_inspect_invalid")
    image = _mapping(image_payload[0])
    image_id = image.get("Id")
    if type(image_id) is not str or not image_id:
        raise ProbeBlocked("web_image_id_missing")
    image_config = _mapping(image.get("Config"))
    image_labels = _mapping(image_config.get("Labels") or {})
    revision = image_labels.get("org.opencontainers.image.revision")
    if revision is not None and type(revision) is not str:
        raise ProbeBlocked("web_oci_revision_invalid")
    return image_ref, image_id, cast(str | None, revision)


def _release_from_image_ref(image_ref: str) -> str | None:
    """Extract a release tag only when it is an exact fourteen-digit tag."""

    final_component = image_ref.rsplit("/", 1)[-1]
    if ":" not in final_component or "@" in final_component:
        return None
    tag = final_component.rsplit(":", 1)[-1]
    return tag if RELEASE_RE.fullmatch(tag) else None


def _container_metadata(
    container: dict[str, Any],
    *,
    service: str,
    project: str,
    image_info: tuple[str, str, str | None] | None = None,
) -> dict[str, object]:
    """Project non-secret Docker metadata for one container."""

    state = _mapping(container.get("State"))
    config = _mapping(container.get("Config"))
    image_ref = image_info[0] if image_info else config.get("Image")
    image_id = image_info[1] if image_info else container.get("Image")
    revision = image_info[2] if image_info else None
    if type(image_ref) is not str or type(image_id) is not str:
        raise ProbeBlocked("container_image_metadata_missing")
    started_at = _parse_utc(state.get("StartedAt"))
    health_value: object = None
    health = state.get("Health")
    if isinstance(health, dict):
        health_value = health.get("Status")
    restart_count = container.get("RestartCount", 0)
    if type(restart_count) is not int or restart_count < 0:
        raise ProbeBlocked("container_restart_count_invalid")
    name = container.get("Name")
    return {
        "id": container.get("Id"),
        "name": name[1:] if type(name) is str and name.startswith("/") else name,
        "service": service,
        "project": project,
        "configured_image": image_ref,
        "image_id": image_id,
        "oci_revision": revision,
        "release_id": _release_from_image_ref(image_ref),
        "started_at": _utc_text(started_at),
        "status": state.get("Status"),
        "health": health_value,
        "restart_count": restart_count,
    }


def _assert_web_identity(metadata: dict[str, object]) -> None:
    """Stop before network requests when the deployed candidate is different."""

    if (
        metadata.get("release_id") != EXPECTED_RELEASE
        or metadata.get("oci_revision") != EXPECTED_COMMIT
        or metadata.get("image_id") != EXPECTED_IMAGE_ID
        or not COMMIT_RE.fullmatch(str(metadata.get("oci_revision") or ""))
    ):
        raise ProbeBlocked("candidate_identity_mismatch")


def _network_ip(
    container: dict[str, Any],
    *,
    shared_with: set[str],
) -> tuple[str, str]:
    """Select one IPv4/IPv6 address on a network shared with the web service."""

    settings = _mapping(container.get("NetworkSettings"))
    networks = _mapping(settings.get("Networks"))
    for network_name in sorted(shared_with):
        network = _mapping(networks.get(network_name))
        address = network.get("IPAddress")
        if type(address) is str and address:
            try:
                ipaddress.ip_address(address)
            except ValueError as exc:
                raise ProbeBlocked("prometheus_container_ip_invalid") from exc
            return network_name, address
    raise ProbeBlocked("prometheus_shared_network_ip_missing")


def _network_names(container: dict[str, Any]) -> set[str]:
    """Return Docker network names without aliases or environment data."""

    settings = _mapping(container.get("NetworkSettings"))
    networks = _mapping(settings.get("Networks"))
    return {key for key in networks if type(key) is str and key}


def _volume_metadata(containers: dict[str, dict[str, Any]]) -> list[dict[str, object]]:
    """Collect named-volume metadata while omitting host source paths."""

    result: list[dict[str, object]] = []
    seen: set[tuple[str, str]] = set()
    for service, container in containers.items():
        mounts = container.get("Mounts")
        if not isinstance(mounts, list):
            continue
        for raw_mount in mounts:
            mount = _mapping(raw_mount)
            mount_type = mount.get("Type")
            destination = mount.get("Destination")
            if type(destination) is not str or type(mount_type) is not str:
                raise ProbeBlocked("container_mount_metadata_invalid")
            if mount_type != "volume":
                result.append(
                    {
                        "container_service": service,
                        "destination": destination,
                        "type": mount_type,
                        "read_only": mount.get("RW") is False,
                    }
                )
                continue
            name = mount.get("Name")
            if type(name) is not str or not name:
                raise ProbeBlocked("named_volume_name_missing")
            key = (service, name)
            if key in seen:
                continue
            seen.add(key)
            inspected = _docker_json(["volume", "inspect", name])
            if not isinstance(inspected, list) or len(inspected) != 1:
                raise ProbeBlocked("volume_inspect_invalid")
            volume = _mapping(inspected[0])
            result.append(
                {
                    "container_service": service,
                    "destination": destination,
                    "type": mount_type,
                    "name": name,
                    "read_only": mount.get("RW") is False,
                    "driver": volume.get("Driver"),
                    "mountpoint": volume.get("Mountpoint"),
                    "scope": volume.get("Scope"),
                }
            )
    return result


def _origin(value: str) -> str:
    """Validate and normalize a credential-free HTTPS origin."""

    parsed = urlsplit(value)
    if (
        parsed.scheme != "https"
        or not parsed.netloc
        or parsed.username
        or parsed.password
        or parsed.query
        or parsed.fragment
        or parsed.path not in ("", "/")
    ):
        raise ProbeBlocked("prometheus_origin_invalid")
    return urlunsplit(("https", parsed.netloc, "", "", ""))


def _credentials_metadata() -> tuple[dict[str, object], str]:
    """Load host-only Basic Auth values and return only safe metadata plus auth."""

    try:
        stat_result = CREDENTIAL_PATH.stat()
        payload_text = CREDENTIAL_PATH.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ProbeBlocked("prometheus_credentials_unavailable") from exc
    mode = S_IMODE(stat_result.st_mode)
    if mode != 0o600:
        raise ProbeBlocked("prometheus_credentials_mode_invalid")

    def _unique_json_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
        result: dict[str, object] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate credential key")
            result[key] = value
        return result

    try:
        payload = json.loads(payload_text, object_pairs_hook=_unique_json_object)
    except (ValueError, json.JSONDecodeError):
        lines = payload_text.splitlines()
        if len(lines) != 2:
            raise ProbeBlocked("prometheus_credentials_format_invalid")
        key_values: dict[str, str] = {}
        for line in lines:
            if "=" not in line:
                raise ProbeBlocked("prometheus_credentials_format_invalid")
            key, value = line.split("=", 1)
            if key not in {"username", "password"} or key in key_values:
                raise ProbeBlocked("prometheus_credentials_keys_invalid")
            if not value:
                raise ProbeBlocked("prometheus_credentials_values_invalid")
            key_values[key] = value
        if set(key_values) != {"username", "password"}:
            raise ProbeBlocked("prometheus_credentials_keys_invalid")
        values: dict[str, Any] = key_values
    else:
        values = _mapping(payload)
    if set(values) != {"username", "password"}:
        raise ProbeBlocked("prometheus_credentials_keys_invalid")
    username = values.get("username")
    password = values.get("password")
    if type(username) is not str or not username or type(password) is not str or not password:
        raise ProbeBlocked("prometheus_credentials_values_invalid")
    auth_bytes = f"{username}:{password}".encode("utf-8")
    auth_value = base64.b64encode(auth_bytes).decode("ascii")
    metadata: dict[str, object] = {
        "path": str(CREDENTIAL_PATH),
        "mode": f"{mode:04o}",
        "size_bytes": stat_result.st_size,
        "keys": ["password", "username"],
        "credential_values_exposed": False,
    }
    return metadata, auth_value


def _limited_body(response: Any) -> bytes:
    """Read a bounded HTTP body before hashing and base64 encoding it."""

    body = response.read(MAX_RESPONSE_BYTES + 1)
    if len(body) > MAX_RESPONSE_BYTES:
        raise ProbeBlocked("http_response_too_large")
    return body


def _api_payload(body: bytes) -> dict[str, Any] | None:
    """Decode a JSON API body without returning untrusted raw fields in errors."""

    try:
        value = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
    if not isinstance(value, dict):
        return None
    return cast(dict[str, Any], value)


def _base_summary(payload: dict[str, Any] | None) -> dict[str, object]:
    """Return a small status/type summary for one JSON response."""

    if payload is None:
        return {"json": "unavailable"}
    data = payload.get("data")
    return {
        "api_status": payload.get("status") if type(payload.get("status")) is str else None,
        "data_type": type(data).__name__,
        "data_keys": sorted(data) if isinstance(data, dict) else [],
    }


def _vector_summary(payload: dict[str, Any] | None) -> dict[str, object]:
    """Summarize a Prometheus vector without making a gate decision."""

    summary = _base_summary(payload)
    if payload is None or not isinstance(payload.get("data"), dict):
        return summary
    data = _mapping(payload["data"])
    results = data.get("result")
    if not isinstance(results, list):
        return {**summary, "result_count": None}
    label_keys: set[str] = set()
    values: Counter[str] = Counter()
    for item in results:
        record = _mapping(item)
        labels = record.get("metric")
        if isinstance(labels, dict):
            label_keys.update(key for key in labels if type(key) is str)
        sample = record.get("value")
        if isinstance(sample, list) and len(sample) == 2 and type(sample[1]) is str:
            values[sample[1]] += 1
    return {
        **summary,
        "result_count": len(results),
        "label_keys": sorted(label_keys),
        "sample_value_counts": dict(sorted(values.items())),
    }


def _targets_summary(payload: dict[str, Any] | None) -> dict[str, object]:
    """Summarize Prometheus target counts and reported health values."""

    summary = _base_summary(payload)
    if payload is None or not isinstance(payload.get("data"), dict):
        return summary
    data = _mapping(payload["data"])
    active = data.get("activeTargets")
    dropped = data.get("droppedTargets")
    active_items = active if isinstance(active, list) else []
    health = Counter(
        str(_mapping(item).get("health"))
        for item in active_items
        if isinstance(item, dict)
    )
    return {
        **summary,
        "active_target_count": len(active_items) if isinstance(active, list) else None,
        "dropped_target_count": len(dropped) if isinstance(dropped, list) else None,
        "health_counts": dict(sorted(health.items())),
    }


def _rules_summary(payload: dict[str, Any] | None) -> dict[str, object]:
    """Summarize Prometheus rule groups without copying rule expressions."""

    summary = _base_summary(payload)
    if payload is None or not isinstance(payload.get("data"), dict):
        return summary
    data = _mapping(payload["data"])
    groups = data.get("groups")
    group_items = groups if isinstance(groups, list) else []
    rule_count = 0
    health = Counter()
    for item in group_items:
        group = _mapping(item)
        rules = group.get("rules")
        if isinstance(rules, list):
            rule_count += len(rules)
            for rule in rules:
                if isinstance(rule, dict) and type(rule.get("health")) is str:
                    health[cast(str, rule["health"])] += 1
    return {
        **summary,
        "group_count": len(group_items),
        "rule_count": rule_count,
        "health_counts": dict(sorted(health.items())),
    }


def _response(
    *,
    opener: Any,
    url: str,
    path: str,
    query: dict[str, str] | None = None,
    basic_auth: str | None = None,
    summary_kind: str,
) -> dict[str, object]:
    """Perform one GET and preserve its raw body hash/base64 without headers."""

    query_values = query or {}
    target = f"{url.rstrip('/')}{path}"
    if query_values:
        target = f"{target}?{urlencode(query_values)}"
    request = Request(target, method="GET", headers={"Accept": "application/json"})
    if basic_auth is not None:
        request.add_header("Authorization", f"Basic {basic_auth}")
    body = b""
    status: int | None = None
    content_type: str | None = None
    transport_error: str | None = None
    try:
        with opener.open(request, timeout=MAX_REQUEST_SECONDS) as response:
            status = response.status
            content_type = response.headers.get_content_type()
            body = _limited_body(response)
    except HTTPError as exc:
        status = exc.code
        content_type = exc.headers.get_content_type() if exc.headers else None
        body = _limited_body(exc)
    except (OSError, ProbeBlocked) as exc:
        transport_error = exc.code if isinstance(exc, ProbeBlocked) else type(exc).__name__
    payload = _api_payload(body)
    if summary_kind == "vector":
        summary = _vector_summary(payload)
    elif summary_kind == "targets":
        summary = _targets_summary(payload)
    elif summary_kind == "rules":
        summary = _rules_summary(payload)
    else:
        summary = _base_summary(payload)
    return {
        "request": {"method": "GET", "path": path, "query": query_values},
        "status": status,
        "content_type": content_type,
        "transport_error": transport_error,
        "body_bytes": len(body),
        "body_sha256": hashlib.sha256(body).hexdigest(),
        "body_base64": base64.b64encode(body).decode("ascii"),
        "summary": summary,
    }


def _count_series(payload: dict[str, Any] | None) -> int | None:
    """Read a bounded count(web_to_tui_migration_events_total) vector."""

    if payload is None or payload.get("status") != "success":
        return None
    data = payload.get("data")
    if not isinstance(data, dict) or data.get("resultType") != "vector":
        return None
    result = data.get("result")
    if not isinstance(result, list) or len(result) != 1:
        return None
    sample = _mapping(result[0]).get("value")
    if not isinstance(sample, list) or len(sample) != 2 or type(sample[1]) is not str:
        return None
    try:
        number = float(sample[1])
    except ValueError:
        return None
    if not math.isfinite(number) or number < 0 or number != int(number):
        return None
    return int(number)


def _step_seconds(duration: float, series_count: int) -> int:
    """Choose a range step whose requested evaluation budget is <= 11,000."""

    budget_series = max(1, series_count)
    points_per_series = max(1, MAX_PROMETHEUS_POINTS // budget_series)
    intervals = max(1, points_per_series - 1)
    return max(1, math.ceil(max(0.0, duration) / intervals))


def _timestamp_summary(
    payload: dict[str, Any] | None,
    *,
    start_epoch: float,
    start_text: str,
    end_text: str,
    step_seconds: int,
) -> dict[str, object]:
    """Summarize real source timestamps and discard pre-start values."""

    summary = _base_summary(payload)
    if payload is None or not isinstance(payload.get("data"), dict):
        return {**summary, "source_timestamp_count": 0, "synthetic_zero_inserted": False}
    data = _mapping(payload["data"])
    results = data.get("result")
    if data.get("resultType") != "matrix" or not isinstance(results, list):
        return {**summary, "source_timestamp_count": 0, "synthetic_zero_inserted": False}
    returned_points = 0
    before_start = 0
    source_timestamps: list[float] = []
    for raw_result in results:
        result = _mapping(raw_result)
        values = result.get("values")
        if not isinstance(values, list):
            continue
        returned_points += len(values)
        for raw_sample in values:
            if not isinstance(raw_sample, list) or len(raw_sample) != 2:
                continue
            try:
                source_timestamp = float(raw_sample[1])
            except (TypeError, ValueError):
                continue
            if not math.isfinite(source_timestamp):
                continue
            if source_timestamp < start_epoch:
                before_start += 1
            else:
                source_timestamps.append(source_timestamp)
    first = min(source_timestamps) if source_timestamps else None
    last = max(source_timestamps) if source_timestamps else None
    return {
        **summary,
        "result_type": "matrix",
        "series_count": len(results),
        "returned_point_count": returned_points,
        "source_timestamp_count": len(source_timestamps),
        "pre_web_start_timestamp_count": before_start,
        "first_source_timestamp": _utc_text(datetime.fromtimestamp(first, UTC)) if first else None,
        "last_source_timestamp": _utc_text(datetime.fromtimestamp(last, UTC)) if last else None,
        "query_start": start_text,
        "query_end": end_text,
        "step_seconds": step_seconds,
        "max_points": MAX_PROMETHEUS_POINTS,
        "synthetic_zero_inserted": False,
        "point_limit_exceeded": returned_points > MAX_PROMETHEUS_POINTS,
    }


def _collect(origin: str) -> dict[str, object]:
    """Collect Docker metadata and the four internal plus three HTTPS GETs."""

    web = _running_service("web")
    web_labels = _labels(web)
    project = web_labels.get("com.docker.compose.project")
    if not project:
        raise ProbeBlocked("canonical_web_project_missing")
    image_info = _image_info(web)
    containers_raw = {
        "web": web,
        "prometheus": _running_service("prometheus", project=project),
        "caddy": _running_service("caddy", project=project),
    }
    metadata = {
        "web": _container_metadata(web, service="web", project=project, image_info=image_info),
        "prometheus": _container_metadata(
            containers_raw["prometheus"], service="prometheus", project=project
        ),
        "caddy": _container_metadata(containers_raw["caddy"], service="caddy", project=project),
    }
    _assert_web_identity(metadata["web"])
    web_started = _parse_utc(cast(dict[str, object], metadata["web"])["started_at"])
    shared_networks = _network_names(web) & _network_names(containers_raw["prometheus"])
    network_name, prometheus_ip = _network_ip(
        containers_raw["prometheus"], shared_with=shared_networks
    )
    volumes = _volume_metadata(containers_raw)
    credential_metadata, basic_auth = _credentials_metadata()
    normalized_origin = _origin(origin)
    opener = build_opener(ProxyHandler({}), _NoRedirect())
    responses: list[dict[str, object]] = []
    internal_base = f"http://{prometheus_ip}:9090"
    for name, path, summary_kind in (
        ("prometheus_flags", "/api/v1/status/flags", "base"),
        ("prometheus_runtimeinfo", "/api/v1/status/runtimeinfo", "base"),
        ("prometheus_targets", "/api/v1/targets", "targets"),
        ("prometheus_rules", "/api/v1/rules", "rules"),
    ):
        response = _response(
            opener=opener,
            url=internal_base,
            path=path,
            summary_kind=summary_kind,
        )
        response["name"] = name
        responses.append(response)

    end = datetime.now(UTC)
    if end < web_started:
        raise ProbeBlocked("web_started_at_in_future")
    up_response = _response(
        opener=opener,
        url=normalized_origin,
        path="/internal/prometheus/api/v1/query",
        query={"query": "up"},
        basic_auth=basic_auth,
        summary_kind="vector",
    )
    up_response["name"] = "prometheus_up"
    responses.append(up_response)
    count_query = "count(web_to_tui_migration_events_total)"
    count_response = _response(
        opener=opener,
        url=normalized_origin,
        path="/internal/prometheus/api/v1/query",
        query={"query": count_query},
        basic_auth=basic_auth,
        summary_kind="vector",
    )
    count_response["name"] = "migration_series_count"
    responses.append(count_response)
    count_payload = _api_payload(base64.b64decode(cast(str, count_response["body_base64"])))
    series_count = _count_series(count_payload)
    if series_count is None:
        raise ProbeBlocked("migration_series_count_unavailable")
    start_epoch = web_started.timestamp()
    duration = max(0.0, end.timestamp() - start_epoch)
    step_seconds = _step_seconds(duration, series_count)
    range_response = _response(
        opener=opener,
        url=normalized_origin,
        path="/internal/prometheus/api/v1/query_range",
        query={
            "query": "timestamp(web_to_tui_migration_events_total)",
            "start": f"{start_epoch:.6f}",
            "end": f"{end.timestamp():.6f}",
            "step": str(step_seconds),
        },
        basic_auth=basic_auth,
        summary_kind="base",
    )
    range_body = base64.b64decode(cast(str, range_response["body_base64"]))
    range_payload = _api_payload(range_body)
    range_response["name"] = "migration_timestamp_query_range"
    range_response["summary"] = _timestamp_summary(
        range_payload,
        start_epoch=start_epoch,
        start_text=_utc_text(web_started),
        end_text=_utc_text(end),
        step_seconds=step_seconds,
    )
    responses.append(range_response)
    return {
        "schema_version": "tui02-retained-readonly-probe.v1",
        "environment": "production",
        "collection_mode": "read_only",
        "probe_status": "collected",
        "collected_at": _utc_text(end),
        "candidate": {
            "release_id": EXPECTED_RELEASE,
            "commit": EXPECTED_COMMIT,
            "image_id": EXPECTED_IMAGE_ID,
        },
        "containers": metadata,
        "prometheus_network": {"name": network_name, "ip": prometheus_ip},
        "volumes": volumes,
        "credentials": credential_metadata,
        "query_origin": normalized_origin,
        "web_started_at": _utc_text(web_started),
        "prometheus_series_count_at_query": series_count,
        "responses": responses,
        "side_effects": {
            "remote_write": False,
            "deployment": False,
            "restart": False,
            "configuration_change": False,
            "backup": False,
            "load_test": False,
            "business_request": False,
        },
    }


def main() -> int:
    """Run one explicit-origin, read-only candidate probe."""

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--origin", required=True, help="Credential-free HTTPS Prometheus origin")
    args = parser.parse_args()
    try:
        report = _collect(args.origin)
